<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\WebAuthn\Application\Usecase\BeginRegistration;

use DateTimeImmutable;
use Ramsey\Uuid\Uuid;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\WebAuthnChallenge;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnChallengeGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnCredentialGateway;
use Civi\Lughauth\Shared\Exception\NotFoundException;

/**
 * Application use case that initiates the WebAuthn credential registration ceremony.
 *
 * Validates that both the tenant and the requesting user exist and are consistent
 * (the user must belong to the given tenant), then generates a cryptographically
 * random challenge stored as a pending WebAuthnChallenge of type "register". The
 * returned PublicKeyCredentialCreationOptions include the user's display information
 * and an excludeCredentials list built from the user's already-registered passkeys,
 * preventing duplicate registrations on the same authenticator device. The challenge
 * expires after five minutes; FinishRegistrationUsecase must be invoked within that
 * window to complete the ceremony and persist the new credential.
 */
final class BeginRegistrationUsecase
{
    public function __construct(
        private readonly TenantReadGateway $tenants,
        private readonly UserReadGateway $users,
        private readonly WebAuthnChallengeGateway $challengeGateway,
        private readonly WebAuthnCredentialGateway $credentialGateway,
    ) {
    }

    /**
     * Creates and persists a registration challenge bound to the user and tenant.
     * Returns the PublicKeyCredentialCreationOptions array ready to be JSON-encoded
     * and passed to the browser's navigator.credentials.create() call.
     */
    public function begin(string $userUid, string $tenantName, string $rpId, string $rpName): array
    {
        $tenant = $this->tenants->findOneByName($tenantName);
        if (!$tenant) {
            throw new NotFoundException('tenant ' . $tenantName);
        }

        $user = $this->users->findOneByUid($userUid);
        if (!$user || $user->getTenant()->uid() !== $tenant->uid()) {
            throw new NotFoundException('user ' . $userUid);
        }

        $challengeBytes = random_bytes(32);
        $challenge = rtrim(strtr(base64_encode($challengeBytes), '+/', '-_'), '=');
        $challengeId = Uuid::uuid4()->toString();

        $this->challengeGateway->store(new WebAuthnChallenge(
            challengeId: $challengeId,
            tenantId: $tenant->uid() ?? $tenantName,
            userUid: $userUid,
            challenge: $challenge,
            type: 'register',
            optionsJson: null,
            createdAt: new DateTimeImmutable(),
            expiresAt: new DateTimeImmutable('+5 minutes'),
            verified: false,
            verifiedAt: null,
            verifiedUserUid: null,
            verifiedUsername: null,
        ));

        $existingCredentials = $this->credentialGateway->findByUser($userUid, $tenant->uid() ?? $tenantName);

        return [
            'challengeId' => $challengeId,
            'challenge' => $challenge,
            'rp' => ['name' => $rpName, 'id' => $rpId],
            'user' => [
                'id' => rtrim(strtr(base64_encode($userUid), '+/', '-_'), '='),
                'name' => $user->getEmail() ?? $user->getName(),
                'displayName' => $user->getName() ?? $user->getEmail(),
            ],
            'pubKeyCredParams' => [
                ['alg' => -7,   'type' => 'public-key'],
                ['alg' => -257, 'type' => 'public-key'],
            ],
            'authenticatorSelection' => [
                'residentKey' => 'preferred',
                'userVerification' => 'preferred',
            ],
            'excludeCredentials' => array_map(
                fn ($c) => ['id' => $c->credentialId, 'type' => 'public-key'],
                $existingCredentials
            ),
            'timeout' => 60000,
            'attestation' => 'none',
        ];
    }
}
